export function seedReports(){return Array.from({length:84},(_,i)=>{const location=locations[i%8],type=['heavy_rain','flood','storm','heavy_rain','heatwave','fog','cyclone','other'][i%8];return {id:`demo-${String(i+1).padStart(4,'0')}`,event_type:type,location,location_name:location.name,latitude:location.latitude,longitude:location.longitude,severity:['moderate','high','low'][i%3],description:descriptions[i%6],event_time:new Date(Date.now()-(i*1.7+.2)*3600000).toISOString(),status:i%7===0?'rejected':i%3===0?'pending':'verified',row_version:1,evidence:[{type:'photo',description:'Street conditions submitted by the reporter',has_link:true}],suggestion:i%7===0?'Possible duplicate':i%3===0?'Source needs review':'Category matched',history:[]};});}
